"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Moonlit Meadow Tales', 'author': 'Signature original', 'genre': 'Fairy Forests', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "Wren found a golden key on the first day of spring, under the oldest oak in the Moonlit Meadow, where the fireflies danced like sparks. It glowed. Things that glow, Wren's grandmother always said, are either magic or trouble. Often both.\n\na talking fox appeared as if called — perhaps by the glow, perhaps by fate. 'That's a golden key,' a talking fox said, eyes wide. 'The stories say it chooses someone. It seems it chose you.'\n\nThat night the Sorrow Spider's shadow fell over the Moonlit Meadow: the brook ran backwards, the mushrooms glowed red, the stars went out one by one. Wren held a golden key tight. It pulsed, warm as a heartbeat."}, {'n': 2, 'title': 'The Journey', 'text': "At the edge of the Moonlit Meadow, they looked back at the darkened woods and forward at the Sorrow Spider's thorn castle. 'Together?' Wren asked. 'Always,' said a talking fox. And in they went.\n\nThe path through the Moonlit Meadow was a storybook: a brook that sang, mushrooms that lit the way, an oak that bowed. a talking fox knew every tale and told them walking, which made the miles shorter and the dark less dark.\n\nThey escaped by brook-light, laughing and shaking. a golden key glowed brighter, as if proud. Wren was starting to understand: it wasn't just a magical object. It was a friend, too."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "the Sorrow Spider's castle was made of thorns and sulks. The door asked for a password. a talking fox guessed 'please' — and it worked, because manners are magic the Sorrow Spider never learned.\n\nthe Sorrow Spider's jar cracked. A single star escaped — then another, then a flood of starlight, pouring back to the Moonlit Meadow. the Sorrow Spider shrank with every star, smaller, smaller, till only a grumble remained. The Grumble King, indeed.\n\nInside, everything was grey: grey tapestries, grey servants, a grey throne where the Sorrow Spider sat, holding the stolen starlight of the Moonlit Meadow in a jar. 'Mine,' the Sorrow Spider hissed. 'All mine.'"}, {'n': 4, 'title': 'Starlight Restored', 'text': "kindness is magic — Wren wrote it in the family book, under the date, in the careful letters of someone who means it forever.\n\na golden key chose to stay with Wren — or Wren chose to stay with it; by now they weren't sure there was a difference. It sits by the bed, glowing softly, a nightlight of pure story.\n\nthe Moonlit Meadow celebrated: the fireflies spelled Wren's name, the oak dropped acorns of thanks, the wise owl composed a ballad with a talking fox as the hero — a talking fox insisted Wren was the hero; they compromised on both."}, {'n': 5, 'title': 'The Promise Kept', 'text': "Wren grew, as heroes do, but never grew out of the Moonlit Meadow. Every spring they check the old oak. Every night a golden key glows. Every tale a talking fox tells starts, 'When we saved the stars...'\n\na talking fox is older now, greyer, no less brave. They still walk together, still argue about the ballad, still keep the grumble-jar dusted. Friendship, like starlight, doesn't fade if you tend it.\n\nkindness is magic. In the Moonlit Meadow, in the starlight, in every heart that hears the tale: the promise kept, the story told, the magic real."}, {'n': 6, 'title': 'Bedtime', 'text': "kindness is magic. Goodnight.\n\nSleep tight, the Moonlit Meadow. The dark is just the blanket. The light is a golden key, and a golden key is here, and Wren is here, and a talking fox is here.\n\nAnd now it's bedtime in the Moonlit Meadow, and a golden key glows soft, and a talking fox is telling the story one more time, to one more sleepy listener. 'The end,' a talking fox says."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

